// TestFilesWithRemainingAgentChanges_StashedFile tests that files on the shadow branch
// but not on disk (e.g. stashed) are NOT carried forward, since buildTreeWithChanges
// would treat them as deletions, creating a no-op shadow branch.
func TestFilesWithRemainingAgentChanges_StashedFile(t *testing.T) {
	t.Parallel()
	dir := setupGitRepo(t)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	// Create shadow branch with two files
	createShadowBranchWithContent(t, repo, "abc1234", "e3b0c4", map[string][]byte{
		"fileA.txt": []byte("content A"),
		"fileB.txt": []byte("content B"),
	})

	// Write fileA to disk and commit it; fileB is NOT on disk (simulates stash)
	require.NoError(t, os.WriteFile(filepath.Join(dir, "fileA.txt"), []byte("content A"), 0o644))
	wt, err := repo.Worktree()
	require.NoError(t, err)
	_, err = wt.Add("fileA.txt")
	require.NoError(t, err)
	headCommit, err := wt.Commit("Add file A only", &git.CommitOptions{
		Author: &object.Signature{Name: "Test", Email: "test@test.com", When: time.Now()},
	})
	require.NoError(t, err)

	commit, err := repo.CommitObject(headCommit)
	require.NoError(t, err)

	shadowBranch := checkpoint.ShadowBranchNameForCommit("abc1234", "e3b0c4")
	committedFiles := map[string]struct{}{"fileA.txt": {}}

	// fileB is on shadow branch but NOT on disk (stashed) — should NOT be in remaining
	remaining := filesWithRemainingAgentChanges(context.Background(), repo, shadowBranch, commit, []string{"fileA.txt", "fileB.txt"}, committedFiles)
	assert.Empty(t, remaining, "Stashed file (not on disk) should not be carried forward")
}
